reference_solution:
def maximum_distinct_x_triplet_sum(x,y):
    best={}
    for key,value in zip(x,y):best[key]=max(best.get(key,0),value)
    if len(best)<3:return -1
    return sum(sorted(best.values(),reverse=True)[:3])

